01831 {
01832     IM_ASSERT(num_segments > 0); // Use ImBezierCubicClosestPointCasteljau()
01833     ImVec2 p_last = p1;
01834     ImVec2 p_closest;
01835     float p_closest_dist2 = FLT_MAX;
01836     float t_step = 1.0f / (float)num_segments;
01837     for (int i_step = 1; i_step <= num_segments; i_step++)
01838     {
01839         ImVec2 p_current = ImBezierCubicCalc(p1, p2, p3, p4, t_step * i_step);
01840         ImVec2 p_line = ImLineClosestPoint(p_last, p_current, p);
01841         float dist2 = ImLengthSqr(p - p_line);
01842         if (dist2 < p_closest_dist2)
01843         {
01844             p_closest = p_line;
01845             p_closest_dist2 = dist2;
01846         }
01847         p_last = p_current;
01848     }
01849     return p_closest;
01850 }

