02281 {
02282     IM_ASSERT(filename && mode);
02283     if (out_file_size)
02284         *out_file_size = 0;
02285 
02286     ImFileHandle f;
02287     if ((f = ImFileOpen(filename, mode)) == NULL)
02288         return NULL;
02289 
02290     size_t file_size = (size_t)ImFileGetSize(f);
02291     if (file_size == (size_t)-1)
02292     {
02293         ImFileClose(f);
02294         return NULL;
02295     }
02296 
02297     void* file_data = IM_ALLOC(file_size + padding_bytes);
02298     if (file_data == NULL)
02299     {
02300         ImFileClose(f);
02301         return NULL;
02302     }
02303     if (ImFileRead(file_data, 1, file_size, f) != file_size)
02304     {
02305         ImFileClose(f);
02306         IM_FREE(file_data);
02307         return NULL;
02308     }
02309     if (padding_bytes > 0)
02310         memset((void*)(((char*)file_data) + file_size), 0, (size_t)padding_bytes);
02311 
02312     ImFileClose(f);
02313     if (out_file_size)
02314         *out_file_size = file_size;
02315 
02316     return file_data;
02317 }

02247 {
02248 #if defined(_WIN32) && !defined(IMGUI_DISABLE_WIN32_FUNCTIONS) && !defined(__CYGWIN__) && !defined(__GNUC__)
02249     // We need a fopen() wrapper because MSVC/Windows fopen doesn't handle UTF-8 filenames.
02250     // Previously we used ImTextCountCharsFromUtf8/ImTextStrFromUtf8 here but we now need to support ImWchar16 and ImWchar32!
02251     const int filename_wsize = ::MultiByteToWideChar(CP_UTF8, 0, filename, -1, NULL, 0);
02252     const int mode_wsize = ::MultiByteToWideChar(CP_UTF8, 0, mode, -1, NULL, 0);
02253 
02254     // Use stack buffer if possible, otherwise heap buffer. Sizes include zero terminator.
02255     // We don't rely on current ImGuiContext as this is implied to be a helper function which doesn't depend on it (see #7314).
02256     wchar_t local_temp_stack[FILENAME_MAX];
02257     ImVector<wchar_t> local_temp_heap;
02258     if (filename_wsize + mode_wsize > IM_ARRAYSIZE(local_temp_stack))
02259         local_temp_heap.resize(filename_wsize + mode_wsize);
02260     wchar_t* filename_wbuf = local_temp_heap.Data ? local_temp_heap.Data : local_temp_stack;
02261     wchar_t* mode_wbuf = filename_wbuf + filename_wsize;
02262     ::MultiByteToWideChar(CP_UTF8, 0, filename, -1, filename_wbuf, filename_wsize);
02263     ::MultiByteToWideChar(CP_UTF8, 0, mode, -1, mode_wbuf, mode_wsize);
02264     return ::_wfopen(filename_wbuf, mode_wbuf);
02265 #else
02266     return fopen(filename, mode);
02267 #endif
02268 }

