02212 {
02213     seed = ~seed;
02214     ImU32 crc = seed;
02215     const unsigned char* data = (const unsigned char*)data_p;
02216     const ImU32* crc32_lut = GCrc32LookupTable;
02217     if (data_size != 0)
02218     {
02219         while (data_size-- != 0)
02220         {
02221             unsigned char c = *data++;
02222             if (c == '#' && data_size >= 2 && data[0] == '#' && data[1] == '#')
02223                 crc = seed;
02224             crc = (crc >> 8) ^ crc32_lut[(crc & 0xFF) ^ c];
02225         }
02226     }
02227     else
02228     {
02229         while (unsigned char c = *data++)
02230         {
02231             if (c == '#' && data[0] == '#' && data[1] == '#')
02232                 crc = seed;
02233             crc = (crc >> 8) ^ crc32_lut[(crc & 0xFF) ^ c];
02234         }
02235     }
02236     return ~crc;
02237 }

01899 {
01900     ImVec2 ap = p - a;
