02047 {
02048     char* p = buf;
02049     while (p[0] == ' ' || p[0] == '\t')     // Leading blanks
02050         p++;
02051     char* p_start = p;
02052     while (*p != 0)                         // Find end of string
02053         p++;
02054     while (p > p_start && (p[-1] == ' ' || p[-1] == '\t'))  // Trailing blanks
02055         p--;
02056     if (p_start != buf)                     // Copy memory if we had leading blanks
