01920 {
01921     ImVec2 v0 = b - a;
01922     ImVec2 v1 = c - a;
01923     ImVec2 v2 = p - a;
01924     const float denom = v0.x * v1.y - v1.x * v0.y;
01925     out_v = (v2.x * v1.y - v1.x * v2.y) / denom;
01926     out_w = (v0.x * v2.y - v2.x * v0.y) / denom;
01927     out_u = 1.0f - out_v - out_w;
01928 }

01931 {
01932     ImVec2 proj_ab = ImLineClosestPoint(a, b, p);
01933     ImVec2 proj_bc = ImLineClosestPoint(b, c, p);
01934     ImVec2 proj_ca = ImLineClosestPoint(c, a, p);
01935     float dist2_ab = ImLengthSqr(p - proj_ab);
01936     float dist2_bc = ImLengthSqr(p - proj_bc);
01937     float dist2_ca = ImLengthSqr(p - proj_ca);
01938     float m = ImMin(dist2_ab, ImMin(dist2_bc, dist2_ca));
01939     if (m == dist2_ab)
01940         return proj_ab;
01941     if (m == dist2_bc)
01942         return proj_bc;
01943     return proj_ca;
01944 }
